  internal static void FitToWorkingArea(Window window,Rect area,double width,double height,double minWidth,double minHeight){if(area.IsEmpty||area.Width<=0||area.Height<=0)return;window.MinWidth=Math.Min(minWidth,area.Width);window.MinHeight=Math.Min(minHeight,area.Height);window.Width=Math.Min(width,area.Width);window.Height=Math.Min(height,area.Height);window.WindowStartupLocation=WindowStartupLocation.Manual;window.Left=area.Left+(area.Width-window.Width)/2;window.Top=area.Top+(area.Height-window.Height)/2;}
  static Brush Color(string hex){return new SolidColorBrush((System.Windows.Media.Color)ColorConverter.ConvertFromString(hex));}
  TextBlock Text(string value,double size=14,bool bold=false,Brush brush=null){return new TextBlock{Text=value,FontSize=size,FontWeight=bold?FontWeights.SemiBold:FontWeights.Normal,Foreground=brush??ink,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,3,0,3)};}
