  async Task PopulateFilters(){try{var all=await Task.Run(()=>runtime.Store.Choices());loading=true;Fill(tools,all["tool"]);Fill(models,all["model"]);Fill(projects,all["project"]);Fill(devices,all["device"]);Fill(accounts,all["account"]);loading=false;}catch{loading=false;}}
  void Fill(ComboBox combo,IEnumerable<string> values){foreach(var v in values.Distinct().OrderBy(x=>x))if(!combo.Items.Contains(v))combo.Items.Add(v);}
  async void RunScan(){try{await runtime.ScanAsync(true);await PopulateFilters();await RefreshAsync();}catch{state.Text="อ่านประวัติไม่สำเร็จ · โปรดลองใหม่";}}
