  async Task RefreshAsync(){if(!runtime.IsHistoryReady)return;int current=++revision;var filter=Filter();bool useUtc=utc.IsChecked==true,hide=runtime.Privacy;try{var result=await Task.Run(()=>{using(var queries=runtime.Queries.Snapshot(filter))return new{Summary=queries.Summarize(filter),Days=queries.Group(filter,"day",useUtc),Hours=queries.Group(filter,"hour",useUtc),Rhythm=queries.Group(filter,"rhythm",useUtc),Models=queries.Group(filter,"model",useUtc),Tools=queries.Group(filter,"tool",useUtc),Projects=queries.Group(filter,"project",useUtc),Devices=queries.Group(filter,"device",useUtc),Sessions=queries.Group(filter,"session",useUtc),QuotaHistory=hide?null:runtime.Store.QuotaHistory(),Details=queries.Detail(filter,hide),Weekly=queries.Weekly(DateTime.UtcNow)};});if(current!=revision||!IsVisible)return;
