   content.Children.Add(Text("ค่า API ประมาณตามราคาอ้างอิงมาตรฐาน 18 ต.ค. 2026 ไม่ใช่ยอดเรียกเก็บหรือค่าสมาชิก · "+result.Summary.UnknownPriceRequests+" events ยังไม่มีราคา · cache write ใช้ราคา 5 นาทีเมื่อไม่ระบุ TTL",11,false,muted));
