   Section(content,"Activity heatmap");content.Children.Add(Heatmap(result.Days,filter,useUtc));content.Children.Add(Text("ข้อมูล 30 วันเป็น event, 90 วันเป็นรายชั่วโมง, 365 วันเป็นรายวัน แล้วรวมรายเดือน UTC · กราฟชั่วโมงใช้เฉพาะ 90 วัน · คลิกวันที่เพื่อดูรายละเอียด / ล้างตัวกรองเพื่อกลับ · ช่องสีเทา = ไม่พบ event ใน logs ที่อ่านได้ · เวลา "+(useUtc?"UTC":TimeZoneInfo.Local.DisplayName),11,false,muted));
   Section(content,"แนวโน้มรายวัน");content.Children.Add(Bars(result.Days.OrderBy(x=>x.Label).ToList(),false));Section(content,"ใช้งานช่วงเวลาไหน");content.Children.Add(Bars(result.Hours.OrderBy(x=>x.Label).ToList(),false));content.Children.Add(Text(String.Join("   ·   ",result.Rhythm.OrderBy(x=>x.Label).Select(x=>x.Label+"  "+x.Tokens.ToString("N0")+" tokens")),12,false,muted));
   Section(content,"เครื่องมือและโมเดล");content.Children.Add(Bars(result.Tools,true));content.Children.Add(Bars(result.Models,true));Section(content,"โปรเจกต์ / เครื่อง / session");if(hide)content.Children.Add(Text("ซ่อนรายละเอียดระหว่างแชร์จอ",13,false,muted));else{content.Children.Add(Bars(result.Projects.Take(12).ToList(),true));content.Children.Add(Bars(result.Devices,true));content.Children.Add(Bars(result.Sessions.Take(8).ToList(),true));}
