   Section(content,"สรุปประจำสัปดาห์");content.Children.Add(Card(Text(result.Weekly,14)));BuildSources();state.Text=runtime.Status+" · เวลาแสดง "+(useUtc?"UTC":"ระบบ")+" · "+(runtime.TaskbarStatus==null?"":runtime.TaskbarStatus()+" · ")+"ค่าใช้จ่ายไม่รวม tool fees, fast mode หรือ regional pricing";
