  Border Metric(string label,string value){var stack=new StackPanel();stack.Children.Add(Text(label,11,false,muted));stack.Children.Add(Text(value,23,true));return Card(stack);}
  UIElement Heatmap(List<InsightGroup> groups,HistoryFilter filter,bool useUtc){var grid=new Grid{HorizontalAlignment=HorizontalAlignment.Left};for(int r=0;r<7;r++)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var map=groups.ToDictionary(g=>g.Label,g=>g.Tokens);long max=groups.Count==0?1:Math.Max(1,groups.Max(g=>g.Tokens));DateTime day=useUtc?filter.From.Date:filter.From.ToLocalTime().Date;DateTime end=useUtc?DateTime.UtcNow.Date:DateTime.Today;DateTime start=day.AddDays(-(int)day.DayOfWeek);for(;day<=end;day=day.AddDays(1)){string key=day.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture);long value;bool has=map.TryGetValue(key,out value);var b=new Border{Width=17,Height=17,Margin=new Thickness(2),CornerRadius=new CornerRadius(3),Background=has?new SolidColorBrush(System.Windows.Media.Color.FromArgb((byte)(65+190*Math.Sqrt((double)value/max)),62,83,223)):line,ToolTip=key+" · "+(has?value.ToString("N0")+" tokens":"ไม่มีข้อมูล")};DateTime clicked=useUtc?DateTime.SpecifyKind(day,DateTimeKind.Utc):DateTime.SpecifyKind(day,DateTimeKind.Local).ToUniversalTime();b.MouseLeftButtonUp+=(s,e)=>{selectedDay=clicked;Refresh();};int column=(int)(day-start).TotalDays/7;while(grid.ColumnDefinitions.Count<=column)grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});Grid.SetColumn(b,column);Grid.SetRow(b,(int)day.DayOfWeek);grid.Children.Add(b);}return Card(new ScrollViewer{HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,Content=grid});}
  UIElement Bars(List<InsightGroup> groups,bool horizontal){if(groups.Count==0)return Card(Text("ยังไม่มี event ที่ตรงกับตัวกรอง",13,false,muted));long max=Math.Max(1,groups.Max(g=>g.Tokens));if(horizontal){var stack=new StackPanel();foreach(var g in groups){stack.Children.Add(Text(g.Label+"    "+g.Tokens.ToString("N0")+" tokens"+(runtime.Privacy||!g.Cost.HasValue?"":" · ≈ "+g.Cost.Value.ToString("N2")+" USD"),12));stack.Children.Add(new ProgressBar{Minimum=0,Maximum=max,Value=g.Tokens,Height=5,Foreground=accent,Background=line,Margin=new Thickness(0,1,0,10)});}return Card(stack);}var row=new UniformGrid{Columns=groups.Count,Height=115,VerticalAlignment=VerticalAlignment.Bottom};foreach(var g in groups){var bar=new Border{Height=Math.Max(2,90.0*g.Tokens/max),Background=accent,VerticalAlignment=VerticalAlignment.Bottom,Margin=new Thickness(2,0,2,0),CornerRadius=new CornerRadius(3),ToolTip=g.Label+" · "+g.Tokens.ToString("N0")+" tokens"};row.Children.Add(bar);}return Card(row);}
  static string Reset(DateTime? time){if(!time.HasValue)return "ไม่ทราบเวลา reset";var remaining=time.Value-DateTime.UtcNow;return remaining.TotalSeconds<=0?"รอรอบใหม่":"reset อีก "+(int)remaining.TotalHours+" ชม. "+remaining.Minutes+" นาที";}
  void BuildSources(){sources.Children.Clear();Section(sources,"สุขภาพการเชื่อมต่อ");sources.Children.Add(Text("รายชื่อบริการที่วัดค่าได้ · ประวัติ token มีเฉพาะ Codex/Claude logs ของโปรไฟล์ระบบนี้",13,false,muted));foreach(var h in runtime.Health()){var stack=new StackPanel();stack.Children.Add(Text(h.Provider+" · "+h.State,17,true));stack.Children.Add(Text(runtime.Privacy?"ซ่อนรายละเอียดการเชื่อมต่อ":h.Help));stack.Children.Add(Text(h.At.HasValue?"อัปเดตล่าสุด "+h.At.Value.ToLocalTime().ToString("g"):"ยังไม่เคยอ่านสำเร็จ",12,false,muted));stack.Children.Add(Button("เปิดการเชื่อมต่อ",settings));sources.Children.Add(Card(stack));}sources.Children.Add(Text(runtime.Status));sources.Children.Add(Text("โควตาที่ polling อย่างเดียวไม่นับเป็นกิจกรรม; ประวัติเริ่มจาก logs ที่ยังมีอยู่เท่านั้น",12,false,muted));}
  void BuildRecovery(DockPanel root){var panel=new StackPanel{MaxWidth=740,HorizontalAlignment=HorizontalAlignment.Left};root.Children.Add(new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});panel.Children.Add(Text("ประวัติในเครื่องยังไม่พร้อม",24,true));panel.Children.Add(Text(runtime.Status));panel.Children.Add(Text("Monitor โควตายังทำงานต่อได้ การกู้จะเก็บฐานเดิมและไฟล์ประกอบไว้ในโฟลเดอร์สำรองที่มีเวลาระบุ ก่อนเริ่มฐานใหม่ การเก็บและซิงค์จะปิดอยู่ งบและการตั้งค่าที่เคยบันทึกอยู่ในสำเนาเดิม",14,false,muted));if(runtime.RecoveryRequired){var recover=Button("เก็บสำเนาและเริ่มประวัติใหม่",()=>{});panel.Children.Add(recover);recover.Click+=async(s,e)=>{if(MessageBox.Show(this,"เก็บฐานประวัติเดิมพร้อม WAL/SHM/journal เป็นสำเนาแยก แล้วเริ่มฐานใหม่? ประวัติ งบ และการตั้งค่าเดิมจะอยู่ในสำเนา ไม่ได้นำกลับมาอัตโนมัติ หากเปิดเก็บภายหลังจะนำเข้า logs ต้นทางที่ยังอยู่ได้", "ยืนยันเริ่มประวัติใหม่",MessageBoxButton.OKCancel,MessageBoxImage.Question)!=MessageBoxResult.OK)return;recover.IsEnabled=false;try{await runtime.RecoverHistoryAsync();MessageBox.Show(this,"เก็บสำเนาเดิมและเริ่มฐานใหม่แล้ว เปิด Insights อีกครั้งเพื่อดูข้อมูล การเก็บและซิงค์ยังปิดอยู่",Title);Close();}catch{panel.Children.Add(Text("กู้ประวัติไม่สำเร็จ · ไฟล์เดิมหรือสำเนายังคงอยู่ ปิดโปรแกรมอื่นที่ใช้ประวัติแล้วเปิด Quorilo ใหม่"));recover.IsEnabled=runtime.RecoveryRequired;}};}panel.Children.Add(Button("เปิดตั้งค่าการเชื่อมต่อ",settings));}
  void BuildBudget(){budget.Children.Clear();if(!runtime.IsHistoryReady)return;if(runtime.Privacy){budget.Children.Add(Text("ซ่อนงบและยอดจ่ายระหว่างแชร์จอ"));return;}Section(budget,"งบรายเดือนและค่าสมาชิก");budget.Children.Add(Text("เพิ่มรายการแยกตามบริการและเดือน กรอกยอดจ่ายจริงเอง แสดงแยกจากค่า API estimate และไม่รวมข้ามสกุลเงิน",13,false,muted));BuildBudgetEditor();var alerts=new CheckBox{Content="เตือนเมื่อใช้เครดิตเร็วกว่าเวลาที่ผ่านไป (พักเตือน 22:00–08:00)",IsChecked=runtime.PaceAlerts,Margin=new Thickness(0,24,0,10)};alerts.Click+=(s,e)=>runtime.PaceAlerts=alerts.IsChecked==true;budget.Children.Add(alerts);if(runtime.CloudServicesAvailable){var sync=new CheckBox{Content="ส่งประวัติผ่าน Companion ที่จับคู่ไว้ (ต้องเปิดซิงค์บนเว็บด้วย)",IsChecked=runtime.Store.Setting("cloudSync","false")=="true",Margin=new Thickness(0,8,0,8)};sync.Click+=(s,e)=>runtime.Store.Set("cloudSync",sync.IsChecked==true?"true":"false");budget.Children.Add(sync);budget.Children.Add(Button("ลองซิงค์เดี๋ยวนี้",()=>{if(runtime.RequestSync!=null)runtime.RequestSync();}));var share=new CheckBox{Content="แนบรหัสโปรเจกต์ที่ hash แล้วใน sync (ไม่ส่งชื่อหรือ absolute path)",IsChecked=runtime.Store.Setting("cloudProjects","false")=="true",Margin=new Thickness(0,8,0,8)};share.Click+=(s,e)=>runtime.Store.Set("cloudProjects",share.IsChecked==true?"true":"false");budget.Children.Add(share);}else budget.Children.Add(Text("Cloud Sync เป็นบริการออนไลน์แยกต่างหาก ยังไม่เปิดใน Free Core",12,false,muted));var meter=new CheckBox{Content="ทดลองแสดง meter บน Windows taskbar เมื่อมีพื้นที่ว่าง",IsChecked=runtime.Store.Setting("meterEnabled","false")=="true",Margin=new Thickness(0,8,0,8)};meter.Click+=(s,e)=>taskbar(meter.IsChecked==true);budget.Children.Add(meter);var provider=new ComboBox{MinWidth=180,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,6,0,6)};provider.Items.Add("ทุกบริการ");foreach(var h in runtime.Health())provider.Items.Add(h.Provider);provider.SelectedItem=runtime.Store.Setting("meterProvider","");if(provider.SelectedIndex<0)provider.SelectedIndex=0;provider.SelectionChanged+=(s,e)=>runtime.Store.Set("meterProvider",provider.SelectedIndex>0?Convert.ToString(provider.SelectedItem):"");budget.Children.Add(Text("บริการบน taskbar"));budget.Children.Add(provider);var window=new ComboBox{MinWidth=180,HorizontalAlignment=HorizontalAlignment.Left};foreach(var label in new[]{"ทุกรอบ","5h","Weekly","Pro","Flash","Quota"})window.Items.Add(label);window.SelectedItem=runtime.Store.Setting("meterWindow","");if(window.SelectedIndex<0)window.SelectedIndex=0;window.SelectionChanged+=(s,e)=>runtime.Store.Set("meterWindow",window.SelectedIndex>0?Convert.ToString(window.SelectedItem):"");budget.Children.Add(Text("รอบเวลาบน taskbar"));budget.Children.Add(window);budget.Children.Add(Text(runtime.TaskbarStatus==null?"Taskbar meter ยังไม่เชื่อม shell":runtime.TaskbarStatus(),12,false,muted));}
  void BuildBudgetEditor(){var editor=new StackPanel();budget.Children.Add(editor);var month=new TextBox{Text=MonthlyBudgetStore.CurrentMonth,Width=140,HorizontalAlignment=HorizontalAlignment.Left,Padding=new Thickness(6),MaxLength=7};editor.Children.Add(Text("เดือน ค.ศ. (YYYY-MM)"));editor.Children.Add(month);var rows=new StackPanel();var totals=new StackPanel();var message=Text("",12,false,muted);var name=new TextBox{Width=270,HorizontalAlignment=HorizontalAlignment.Left,Padding=new Thickness(6),MaxLength=80};var currency=new ComboBox{Width=140,HorizontalAlignment=HorizontalAlignment.Left};foreach(string code in new[]{"THB","USD","EUR","GBP","JPY"})currency.Items.Add(code);currency.SelectedIndex=0;var limit=new TextBox{Text="0",Width=180,HorizontalAlignment=HorizontalAlignment.Left,Padding=new Thickness(6)};var paid=new TextBox{Text="0",Width=180,HorizontalAlignment=HorizontalAlignment.Left,Padding=new Thickness(6)};string editId=null;Action load=null;load=()=>{rows.Children.Clear();totals.Children.Clear();try{var items=runtime.Budgets.Items(month.Text);foreach(var item in items){var selected=item;var row=new StackPanel();row.Children.Add(Text(item.Name+" · "+item.Paid.ToString("N2")+" / งบ "+item.Limit.ToString("N2")+" "+item.Currency,14,true));var buttons=new WrapPanel();buttons.Children.Add(Button("แก้ไข",()=>{editId=selected.Id;name.Text=selected.Name;currency.SelectedItem=selected.Currency;limit.Text=selected.Limit.ToString(CultureInfo.CurrentCulture);paid.Text=selected.Paid.ToString(CultureInfo.CurrentCulture);message.Text="กำลังแก้ไขรายการของเดือน "+selected.Month;}));buttons.Children.Add(Button("ลบรายการ",()=>{if(MessageBox.Show(this,"ลบรายการงบนี้? ไม่เปลี่ยนประวัติ usage",Title,MessageBoxButton.OKCancel,MessageBoxImage.Question)!=MessageBoxResult.OK)return;try{runtime.Budgets.Remove(selected.Id);if(editId==selected.Id){editId=null;name.Text="";limit.Text=paid.Text="0";}load();message.Text="ลบรายการแล้ว";}catch(FormatException error){message.Text=error.Message;}catch{message.Text="บันทึกรายการไม่ได้ · ลองอีกครั้ง";}}));row.Children.Add(buttons);rows.Children.Add(Card(row));}if(items.Count==0)rows.Children.Add(Text("ยังไม่มีรายการของเดือนนี้",13,false,muted));foreach(var total in runtime.Budgets.Totals(month.Text))totals.Children.Add(Text("รวม "+total.Currency+" · ยอดจ่าย "+total.Paid.ToString("N2")+" / งบ "+total.Limit.ToString("N2")+" · "+BudgetStatus(total.Paid,total.Limit),15,true));message.Text="";}catch(FormatException error){message.Text=error.Message;}catch{message.Text="อ่านรายการงบไม่ได้ · ข้อมูลเดิมยังอยู่";}};editor.Children.Add(Button("ดูเดือนนี้",()=>{editId=null;name.Text="";limit.Text=paid.Text="0";load();}));editor.Children.Add(rows);editor.Children.Add(totals);editor.Children.Add(Text("ชื่อรายการ / บริการ"));editor.Children.Add(name);editor.Children.Add(Text("สกุลเงิน"));editor.Children.Add(currency);editor.Children.Add(Text("งบของรายการนี้ (0 = ยังไม่ตั้งงบ)"));editor.Children.Add(limit);editor.Children.Add(Text("ยอดจ่ายจริงของรายการนี้"));editor.Children.Add(paid);editor.Children.Add(message);editor.Children.Add(Button("บันทึกรายการ",()=>{double l,p;if(!Double.TryParse(limit.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out l)||!Double.TryParse(paid.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out p)){message.Text="กรอกจำนวนเงินให้ถูกต้อง";return;}try{if(editId!=null&&runtime.Budgets.Items(null).Any(x=>x.Id==editId&&x.Month!=month.Text))throw new FormatException("กดดูเดือนนี้ก่อนเพิ่มรายการในเดือนอื่น");runtime.Budgets.Save(new MonthlyBudgetItem{Id=editId,Month=month.Text,Name=name.Text,Currency=Convert.ToString(currency.SelectedItem),Limit=l,Paid=p});editId=null;name.Text="";limit.Text=paid.Text="0";load();message.Text="บันทึกแล้ว";}catch(FormatException error){message.Text=error.Message;}catch{message.Text="บันทึกรายการไม่ได้ · ข้อมูลเดิมยังอยู่";}}));editor.Children.Add(Button("เพิ่มรายการใหม่",()=>{editId=null;name.Text="";limit.Text=paid.Text="0";message.Text="เพิ่มรายการใหม่";}));load();}
  static string BudgetStatus(double paid,double limit){string status=InsightBudget.Check(paid,limit,"",0,"");return status=="over"?"ถึงหรือเกินงบ":status=="warning"?"ใกล้ถึงงบ":status=="within"?"อยู่ในงบ":"ยังไม่ตั้งงบ";}
  async void Export(){if(!runtime.IsHistoryReady)return;var filter=Filter();bool hide=runtime.Privacy;var preview=new Window{Title="ตรวจข้อมูลก่อนส่งออก",Owner=this,Width=740,Height=640,MinWidth=520,MinHeight=420,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Background,Foreground=ink,FontFamily=FontFamily};FitToWorkingArea(preview,SystemParameters.WorkArea,740,640,520,420);var panel=new DockPanel{Margin=new Thickness(22)};preview.Content=panel;var format=new ComboBox{Margin=new Thickness(0,0,0,14)};format.Items.Add("JSON");format.Items.Add("CSV");format.SelectedIndex=0;DockPanel.SetDock(format,Dock.Top);panel.Children.Add(format);var buttons=new WrapPanel{Margin=new Thickness(0,14,0,0)};DockPanel.SetDock(buttons,Dock.Bottom);panel.Children.Add(buttons);buttons.Children.Add(Button("เลือกที่บันทึก",()=>preview.DialogResult=true));buttons.Children.Add(Button("ยกเลิก",()=>preview.DialogResult=false));var description=Text(InsightExportPreview.Describe(filter,hide,false),13);format.SelectionChanged+=(s,e)=>description.Text=InsightExportPreview.Describe(filter,hide,format.SelectedIndex==1);panel.Children.Add(new ScrollViewer{Content=description,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});if(preview.ShowDialog()!=true)return;bool csv=format.SelectedIndex==1;var dialog=new SaveFileDialog{Filter=csv?"CSV (*.csv)|*.csv":"JSON (*.json)|*.json",FileName="Quorilo-usage-"+DateTime.Now.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture)+(csv?".csv":".json"),DefaultExt=csv?".csv":".json",AddExtension=true};if(dialog.ShowDialog(this)!=true)return;try{string path=dialog.FileName;state.Text="กำลังส่งออก…";await Task.Run(()=>File.WriteAllText(path,csv?runtime.Queries.Csv(filter,hide):runtime.Queries.Export(filter,hide),new System.Text.UTF8Encoding(false)));state.Text="ส่งออกแล้ว · "+(hide?"ซ่อนรหัสและค่าใช้จ่าย · ยังมีเวลา/โมเดล/token":"มีรหัสโปรเจกต์/เครื่อง/session");}catch{state.Text="ส่งออกไม่ได้ · ตรวจสิทธิ์เขียนไฟล์";}}
 }
